import fs from 'fs';
import path from 'path';
import { DatabaseSchema, RegistrationRecord, AdminCredentials } from './types';

// Define the path to the JSON database
const DB_PATH = path.join(process.cwd(), 'src', 'data', 'db.json');

// Helpers to read and write to the database
export const readDb = (): DatabaseSchema => {
    try {
        const data = fs.readFileSync(DB_PATH, 'utf-8');
        return JSON.parse(data);
    } catch (error) {
        console.error('Error reading DB:', error);
        return { registrations: [], admins: [], finance: [], calendar: [] };
    }
};

export const writeDb = (data: DatabaseSchema) => {
    try {
        fs.writeFileSync(DB_PATH, JSON.stringify(data, null, 2));
    } catch (error) {
        console.error('Error writing DB:', error);
    }
};

// Data Access Methods

export const getRegistrations = () => {
    const db = readDb();
    return db.registrations;
}

export const addRegistration = (registration: RegistrationRecord) => {
    const db = readDb();
    db.registrations.push(registration);
    writeDb(db);
}

export const getAdminByEmail = (email: string) => {
    const db = readDb();
    return db.admins.find(admin => admin.email === email);
}
